/* Escolhe o catálogo e monta o mapa de armazéns.

   O estoque de cada produto vem com a chave do armazém ("bl_1", "shop_3"),
   não com o nome. Sem este mapa a tela mostraria "bl_1" para a equipe, que
   não significa nada para ninguém. Chave que não estiver no mapa aparece
   como veio e é anotada no log — errar caladinho é o que não pode.  */
const est = $getWorkflowStaticData('global');
est.pagina = 1;
est.gravados = 0;
est.custoAchadoEm = '';
est.chavesSemNome = [];

const cat = $('Base · catálogos').first().json || {};
if (cat.status !== 'SUCCESS') {
  throw new Error('Não consegui listar os catálogos: ' + (cat.error_message || JSON.stringify(cat).slice(0, 300)));
}
const inventarios = Object.entries(cat.inventories || {});
if (!inventarios.length) throw new Error('A Base não devolveu nenhum catálogo.');

/* Um catálogo só. Se um dia houver mais de um, o log avisa qual foi lido em
   vez de escolher em silêncio. */
const [idCatalogo, dadosCatalogo] = inventarios[0];

const arm = $('Base · armazéns').first().json || {};
const mapa = {};
(arm.warehouses || []).forEach(w => {
  const chave = String(w.warehouse_type || '') + '_' + String(w.warehouse_id || '');
  mapa[chave] = w.name || chave;
});

console.log('catálogo:', idCatalogo, '·', (dadosCatalogo && dadosCatalogo.name) || '(sem nome)',
            '| catálogos disponíveis:', inventarios.length,
            '| armazéns:', Object.keys(mapa).length, '→', Object.values(mapa).join(', '));

return [{ json: { inventory_id: idCatalogo, mapaArmazens: mapa, pagina: 1 } }];

/* Ids da página. Página vazia encerra o laço devolvendo zero itens — o n8n
   não tem "pare aqui", quem para é a ausência de item. */
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Página de produtos recusada pela Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const ids = Object.keys(r.products || {});
const inicio = $('De onde começar').first().json;

if (!ids.length) {
  const est = $getWorkflowStaticData('global');
  console.log('fim da varredura — ' + est.gravados + ' produtos gravados em ' + (est.pagina - 1) + ' páginas'
    + (est.custoAchadoEm ? (' | custo médio lido do campo "' + est.custoAchadoEm + '"')
                         : ' | NENHUM campo de custo médio encontrado — ver o log de "Montar produtos"')
    + (est.chavesSemNome.length ? (' | armazéns sem nome no mapa: ' + est.chavesSemNome.join(', ')) : ''));
  return [];
}

return [{ json: { ids, inventory_id: inicio.inventory_id } }];

/* Um registro por produto.

   O campo do custo médio é a única coisa que eu não pude conferir contra a
   conta antes de escrever: a rede daqui não alcança a Base. Então em vez de
   cravar um nome e devolver zero calado, o código procura entre os nomes
   plausíveis, usa o primeiro que existir e DIZ no log qual foi. Se nenhum
   existir, o preço fica nulo e a tela mostra um traço — que é a verdade —
   e o log despeja os campos que o produto realmente tem, para acertarmos o
   nome de uma vez. */
const CANDIDATOS_CUSTO = ['average_cost', 'average_landed_cost', 'purchase_price', 'cost_price', 'average_purchase_price'];

const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  throw new Error('Dados dos produtos recusados pela Base: ' + (r.error_message || JSON.stringify(r).slice(0, 300)));
}
const est = $getWorkflowStaticData('global');
const inicio = $('De onde começar').first().json;
const mapa = inicio.mapaArmazens || {};
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const produtos = Object.entries(r.products || {});
if (produtos.length && !est.custoAchadoEm) {
  const amostra = produtos[0][1] || {};
  const achou = CANDIDATOS_CUSTO.find(c => amostra[c] !== undefined && amostra[c] !== null);
  if (achou) est.custoAchadoEm = achou;
  else console.log('nenhum campo de custo entre [' + CANDIDATOS_CUSTO.join(', ') + ']. '
    + 'Campos que este produto tem: ' + Object.keys(amostra).join(', '));
}

const pagina = {};
produtos.forEach(([id, p]) => {
  /* O estoque vem como { "bl_1": 3, "shop_2": 0 }. A ordem é a que a Base
     mandou; não reordeno porque a ordem dela agrupa por tipo de armazém e
     isso ajuda a ler. */
  const armazens = Object.entries(p.stock || {}).map(([chave, qtd]) => {
    if (!mapa[chave] && est.chavesSemNome.indexOf(chave) < 0) est.chavesSemNome.push(chave);
    return { nome: mapa[chave] || chave, qtd: Number(qtd) || 0 };
  });
  const total = armazens.reduce((a, x) => a + x.qtd, 0);
  const custo = est.custoAchadoEm ? Number(p[est.custoAchadoEm]) : NaN;

  pagina['prod_' + id] = {
    id: 'prod_' + id,
    sku: String(p.sku || ''),
    /* EAN é texto, sempre. Ele começa com zero e número come o zero:
       "07897570128400" viraria 7897570128400 e não bate mais com a etiqueta. */
    ean: String(p.ean || ''),
    nome: String(p.name || p.text_fields && p.text_fields.name || ''),
    total: total,
    armazens: armazens,
    precoMedio: (isFinite(custo) && custo > 0) ? custo : null,
    link: 'https://panel-u.baselinker.com/products_catalog.php#product:' + id,
    sincronizadoEm: carimbo,
    _by: 'n8n'
  };
});

est.gravados += Object.keys(pagina).length;
est.pagina += 1;
console.log('página ' + (est.pagina - 1) + ': ' + Object.keys(pagina).length + ' produtos'
  + (est.custoAchadoEm ? ' | custo em "' + est.custoAchadoEm + '"' : ' | sem custo'));

/* Dois ramos: um grava, o outro segue para a próxima página levando o número
   junto. Ler o contador de um nó que rodou muitas vezes é o que quebrava a
   carga histórica; aqui o número viaja dentro do item. */
return [
  [{ json: { pagina: pagina } }],
  [{ json: { proximaPagina: est.pagina, inventory_id: inicio.inventory_id } }]
];
